// Builds a battle scene for two ships: the first one goes on the left.
const api = game.modules.get("skyplane-combat-reverse").api;
const ships = game.actors.filter((actor) => actor.type === "skyplane-combat-reverse.ship");
if (!ships.length) return ui.notifications.warn("There are no skyships.");
const options = ships.map((ship) => `<option value="${ship.uuid}">${foundry.utils.escapeHTML(ship.name)}</option>`).join("");
if (ships.length < 2) return ui.notifications.warn("A battle needs two ships.");
const pair = await foundry.applications.api.DialogV2.prompt({
  window: { title: "Start battle" },
  content: `<div class="form-group"><label>Left</label><select name="left">${options}</select></div>
    <div class="form-group"><label>Right</label><select name="right">${options}</select></div>`,
  ok: { label: "Build the battle scene", callback: (event, button) => [button.form.elements.left.value, button.form.elements.right.value] },
  rejectClose: false
});
if (!pair) return;
if (pair[0] === pair[1]) return ui.notifications.warn("Pick two different ships.");
(await api.startBattle(pair[0], pair[1]))?.view();
